from __future__ import annotations
from abc_creative_gold_v5_101_200_support import make_spec, register_craft
FACTS={
"Athlete":"Person who trains or participates in physical sport; skill develops through practice, recovery, coaching, and appropriate challenge.",
"Bicycle":"Two-wheeled pedal vehicle steered by handlebars; helmet, brakes, fit, and traffic-safe space matter.",
"Cone":"Bright marker defines boundaries, turns, stations, or lanes; it organizes space rather than making the movement itself.",
"Diving Board":"Springing or rigid platform used for supervised diving at a designed pool; depth, rules, and trained supervision are essential.",
"Exercise Mat":"Padded surface cushions floor exercises; thickness and grip should fit the activity.",
"Football":"Ball used in football codes; size, shape, and rules differ between association football, American football, rugby codes, and others.",
"Goggles":"Eye protection or swim eyewear; fit and sport determine whether they block water, wind, debris, or impact.",
"Hoop":"Circular ring can mark a target or movement station; activity and size determine safe use.",
"Inline Skates":"Boots with wheels in one line; helmet and appropriate protective gear plus a smooth safe area reduce injury risk.",
"Jersey":"Sport shirt identifies player/team and provides clothing comfort; it is not protective gear by itself.",
"Kayak":"Small paddle craft typically propelled with a double-bladed paddle; personal flotation and water-safety supervision are essential.",
"Lacrosse Stick":"Shaft with netted head carries, passes, and shoots a lacrosse ball; protective equipment and rules control contact.",
"Mat":"General padded or marked surface; exact sport decides thickness, grip, shock absorption, and boundaries.",
"Number Bib":"Wearable number identifies a competitor; it records identity/order rather than measuring performance.",
"Oar":"Long lever used from a fixed oarlock in rowing; different from a free handheld paddle.",
"Paddle":"Handheld blade pushes against water to propel or steer a craft; blade and shaft design vary by sport.",
"Quad Skates":"Roller skates with two pairs of wheels; helmet and protective gear plus safe surface are important.",
"Racket":"Handled frame with strings or solid face used to strike a ball/shuttle in racket sports; type depends on sport.",
"Soccer Ball":"Round association-football ball kicked, passed, or headed under game rules; size varies by age/group.",
"Tennis Ball":"Felt-covered hollow rubber ball designed to bounce for tennis; racket striking happens in clear court space.",
"Unicycle":"Single-wheel pedal cycle requiring advanced balance; helmet and controlled practice area are important.",
"Vault":"In gymnastics, vault is an apparatus/event involving a run, springboard, support, and landing; trained coaching and mats are essential.",
"Whistle":"Signal device can start/stop play or attract attention; loud use stays away from ears.",
"X-shaped Agility Marker":"X-shaped floor marker indicates a station or foot-placement target; it is a visual cue, not an obstacle to jump blindly.",
"Yellow Jersey":"Yellow sport jersey may identify a team or special competition status; meaning depends on the event.",
"Zigzag Cone":"Cone arranged or marked for zigzag routes; the cone defines a path rather than requiring maximum speed.",
"Archery Target":"Marked surface receives arrows in archery; real archery requires trained supervision, range rules, and controlled shooting lines.",
"Ball":"Round or oval sport object depending game; material, size, bounce, and rules vary widely.",
"Equipment Bag":"Bag stores and transports gear; wet or protective items may need drying rather than sealing away.",
"Frisbee":"Flying disc glides with spin; throwing needs open space away from roads and bystanders.",
"Goal":"Scoring target or boundary in many sports; dimensions and scoring rules depend on the game.",
"Inflatable Pool":"Air-supported shallow pool for water play; children still require constant close adult supervision around any water.",
"Jump Rope":"Rope rotates around a jumper; clear spacing and supervised use prevent trips or entanglement.",
"Kickboard":"Buoyant swim-training board supports arms while practicing kicking; it is not a lifesaving flotation device.",
"Lane Marker":"Line, cone, rope, or float system separates activity lanes; it organizes traffic and fair space.",
"Medal":"Award token recognizes placement, completion, or achievement; it is not sports equipment used to perform the event.",
"Obstacle":"Object or feature to move around, over, or through in a designed course; difficulty should match skill and supervision.",
"Puck":"Flat disk used in hockey variants; hard pucks can travel fast and require sport-specific protective gear.",
"Relay Baton":"Light tube passed between relay runners in an exchange zone; successful handoff matters more than throwing it.",
"Uniform":"Standard sport clothing identifies team or role; protection requires separate sport-specific equipment when needed.",
"Volleyball":"Inflated ball struck over a net in volleyball; teams keep it from touching their court under the rules.",
"Xylophone":"Tuned-bar musical instrument; it is a deliberate non-sport X comparison item, not athletic gear.",
"Cricket Bat":"Flat-bladed bat used by a batter in cricket; ball speed means sport rules and protective equipment matter.",
"Dumbbell":"Handheld resistance weight; load and technique must fit age, strength, and coaching rather than copying adult lifting.",
"Helmet":"Protective headgear designed for a specific activity; correct fit and certification/type matter.",
"Net":"Mesh barrier or target used in many sports; height, tension, and role depend on game.",
"Quoits Ring":"Ring tossed toward a peg or target; soft age-appropriate versions reduce impact risk.",
"Trampoline":"Elastic-bed apparatus returns energy to a jumper; one-at-a-time rules, guarding, and trained supervision reduce serious injury risk.",
"Water Bottle":"Container supports hydration; personal bottles should not be shared mouth-to-mouth.",
"Yoga Mat":"Grippy padded surface supports floor poses and movement; it does not guarantee safe form by itself.",
"Zorb Ball":"Large inflatable sphere designed for zorbing; activity requires professional setup, safe site, and supervision—not casual child play.",
"Skateboard":"Board on four wheels controlled by balance; helmet/protective gear and a traffic-free practice area are important.",
}
ACTIONS={"Diving Board":"Point only; no jumping gesture—name pool supervision.","Archery Target":"Point to the target; no shooting mime.","Trampoline":"Point only; keep both feet still.","Zorb Ball":"Point only; no rolling-body mime.","Vault":"Point only; trace the apparatus shape, no vaulting imitation.","Dumbbell":"Point only; no lifting challenge.","Puck":"Air-trace a flat disk; no slap-shot mime.","Cricket Bat":"Point and air-trace the bat; no swinging near people.","Lacrosse Stick":"Air-trace the stick/head; no checking or swinging.","Whistle":"Point only; no loud whistle sound.","Jump Rope":"Air-draw an arc; no wrapping.","Inline Skates":"Point; mime helmet strap while standing still.","Quad Skates":"Point; mime helmet strap while standing still.","Skateboard":"Point; show helmet gesture, no riding mime.","Unicycle":"Point only; no balance stunt.","Kayak":"Air-paddle slowly while seated/standing still; name flotation gear.","Inflatable Pool":"Point to water picture; keep hands still and name close adult supervision."}
