GOLD_V5_121_125_SPEC_PATCHES={
"0121":S("0121",authorial_intent="Make Sports Gear Cheer a protection-and-role map: protective gear, playing implements, field markers, clothing, craft, and athlete are separate roles; cheering never becomes a catalog of 'gear'.",lyric_identity="A child asks what protects, what propels, what marks space, and what merely identifies a participant.",image_motifs=("helmet/goggles protection","cone boundary","kayak paddle","number bib","vault apparatus"),semantic_arc=("protect","play implements","space markers","identity/apparatus"),forbidden_generic_language=("sports gear cheer","all gear","put it on","every object makes you active"),rhyme_engine="sport-role-rhyme",chorus_rhyme_engine="protect-play-mark-hook",point_of_view="a child classifying sport roles",chorus_function="repeat protect-play-mark",groove_meter="92 BPM measured cheer 4/4",round1_grammar="object -> sport role -> safety/context",round2_grammar="role-neutral recall -> target -> safe gesture",intro_lines=("Goggles can protect eyes, a cone marks space, a paddle moves water, a bib identifies an athlete.","Sports objects do different jobs before anyone starts moving."),hook_lines=("Protect, play, mark—A-B-C!","Name the role before the cheer."),outro_lines=("Whistle stays a signal, medal stays an award, vault stays a coached apparatus.","A to Z leaves every sports object in its real role."),style_blueprint="Measured sports-pop at 92 BPM with dry drum, bass, marimba and short brass-like stabs kept soft. Avoid stadium roar; roles get separate motifs and target words stay clear.",signature_color="sport-role",cue_prefix="Role recall"),
"0122":S("0122",authorial_intent="Make Move and Play Letters a movement-quality song: throw, roll, glide, kick, pass, balance, float, stop and signal are differentiated, while medal/uniform/Xylophone remain non-movement comparison cards.",lyric_identity="A child chooses a movement verb only when the object truly supports it and accepts that some mapped items are organizational or symbolic.",image_motifs=("frisbee glide","relay baton pass","kickboard float support","cone stop","medal card"),semantic_arc=("move objects","move body","mark/control space","non-movement comparison"),forbidden_generic_language=("move and play every item","move it all","medal moves","xylophone sport"),rhyme_engine="movement-quality-rhyme",chorus_rhyme_engine="roll-glide-pass-stop-hook",point_of_view="a child matching movement verbs to sport objects",chorus_function="cycle movement qualities",groove_meter="94 BPM motion-stop pulse",round1_grammar="function plus correct motion, with non-movement exceptions",round2_grammar="motion-neutral retrieval -> exact target -> safe gesture",intro_lines=("A disc can glide, a baton passes, a cone can mean stop, a medal does none of those.","Movement words work only when they match the object."),hook_lines=("Roll, glide, pass, stop—A-B-C!","Choose the verb that fits the sport."),outro_lines=("The whistle signals, the medal rests, the last cone keeps its place.","A to Z ends with motion and non-motion both named honestly."),style_blueprint="Stop-go 94 BPM groove with soft kick, pizzicato bass, marimba and airy guitar. Motion phrases flow; marker/award cards cut to near-silence.",signature_color="movement-quality",cue_prefix="Motion recall"),
"0123":S("0123",authorial_intent="Make Balls Bikes Gear Ride about energy and control: rolling, bouncing, pedaling, paddling, resistance, hydration, and recovery are linked to the right objects without turning the song into an exercise challenge.",lyric_identity="The child watches how energy enters and leaves a movement system, then pauses for gear and recovery.",image_motifs=("ball bounce","bike wheel","paddle push","mat rest","water bottle"),semantic_arc=("input force","motion/control","protection","pause/hydrate/recover"),forbidden_generic_language=("go faster","strong kids only","lift heavy","ride everything"),rhyme_engine="energy-control-rhyme",chorus_rhyme_engine="push-roll-pause-hook",point_of_view="a child observing motion and recovery",chorus_function="repeat push-control-pause",groove_meter="90 BPM exertion-recovery contour",round1_grammar="object physics/function plus age-appropriate boundary",round2_grammar="recall -> target -> low-intensity gesture",intro_lines=("A ball rebounds, a paddle pushes water, a bicycle turns pedal work into wheel motion.","Active play also needs control, protection, water, and rest."),hook_lines=("Push, control, pause—A-B-C!","Movement is more than going faster."),outro_lines=("Water bottle returns, mat lies still, the last motion slows to rest.","A to Z closes on recovery, not exhaustion."),style_blueprint="90 BPM active-folk groove with guitar, bass, soft drum and marimba; energy rises modestly then deliberately drops in recovery sections. No fitness-command chanting.",signature_color="energy-recovery",cue_prefix="Energy recall"),
"0124":S("0124",authorial_intent="Make Active Kids A-Z about challenge scaling: every activity has an easier entry, a skill progression, equipment fit, and a point where trained coaching is needed; activity is not a competition for intensity.",lyric_identity="A child learns that active can mean controlled practice, not stunts; archery, kayaking, skating, trampoline and vault require distinct supervision.",image_motifs=("helmet fit","soft quoits","kayak PFD","skate practice","vault coach card"),semantic_arc=("easy entry","skill progression","protective setup","coach/facility boundary"),forbidden_generic_language=("active kids go hard","be the best","try the stunt","no fear"),rhyme_engine="skill-progression-rhyme",chorus_rhyme_engine="start-practice-progress-hook",point_of_view="a child scaling challenge safely",chorus_function="repeat start-practice-progress",groove_meter="88 BPM progressive 6/8",round1_grammar="sport object -> skill context -> supervision/progression",round2_grammar="safe recall with no stunt gestures",intro_lines=("Start with the skill you can control, then add challenge when equipment, space, and coaching fit.","Active does not mean maximum difficulty."),hook_lines=("Start, practice, progress—A-B-C!","Control comes before challenge."),outro_lines=("Skateboard stays grounded, trampoline stays supervised, vault stays with a coach.","A to Z ends with one safe next step, not a stunt."),style_blueprint="88 BPM progressive folk-pop with piano, guitar, soft percussion and bass; add one layer per progression, never a dramatic 'extreme sports' drop.",signature_color="challenge-scale",cue_prefix="Skill recall"),
"0125":S("0125",authorial_intent="Make Playground Sports Stop-Go a spatial-awareness song: start/stop cues, lanes, goals, nets, obstacle spacing, wheeled traffic, and hydration create shared safe space; kayak and archery remain off-playground comparison cards.",lyric_identity="A child reads space before speed, treating lines and markers as communication between players.",image_motifs=("start cone","lane marker","goal/net","skateboard zone","water break"),semantic_arc=("start/stop","lanes/routes","shared targets","pause/clear area"),forbidden_generic_language=("playground sports all","go go go","race everywhere","kayak playground"),rhyme_engine="space-signal-rhyme",chorus_rhyme_engine="stop-look-route-hook",point_of_view="a child reading shared activity space",chorus_function="repeat stop-look-route",groove_meter="92 BPM stop-go 4/4",round1_grammar="object fact plus spatial role/safety",round2_grammar="recall -> target -> still or directional gesture",intro_lines=("Cone says where, lane says through, whistle can say stop, water break says pause.","Shared sports space works when everyone can read the same signals."),hook_lines=("Stop, look, route—A-B-C!","Space before speed keeps play readable."),outro_lines=("Board wheels stop, baton rests, bottle comes back before the next round.","A to Z leaves the playground lanes clear."),style_blueprint="Stop-go sports groove at 92 BPM with tight bass, woodblock, soft hand drum and marimba; literal stop moments create silence, routes use short moving motifs, ending decelerates cleanly.",signature_color="space-signal",cue_prefix="Space recall"),}
